"""Root-reviewed frozen Arena figure. Generated by its private collector.

Editable source: figure_archers_rig.py. Rebuild/review through that figure's
staged driver; normal builds append this measured copy and keep its AO.
"""
import hashlib
from pathlib import Path
import re
import bpy
import kit

R = 'archers'
VERSION = 'v4'
RUNTIME_SHA256 = 'a5a872f836951ea5783c43cbe5e7cf66811dfd9cab54bace51e8dbe5383927e5'
SOURCE_FINGERPRINT = 'a5ff69fef69050b2bfec4800a130c06f705c597d508bea6d80106982065ab4c3'
RECIPE_FINGERPRINT = '49a1faa101042b1378371d8134a41241b49f19d43fe9dfc68361ca6b9b0a8504'
RUNTIME = Path(__file__).resolve().parent / "runtime" / (R + "-runtime-" + VERSION + ".blend")

def build(root_name=R):
    if root_name != R:
        raise ValueError("The frozen figure identity is fixed")
    if not RUNTIME.is_file():
        raise RuntimeError("Missing root-reviewed runtime " + str(RUNTIME))
    with RUNTIME.open("rb") as stream:
        digest = hashlib.file_digest(stream, "sha256").hexdigest()
    if digest != RUNTIME_SHA256:
        raise RuntimeError("The frozen runtime changed after root review")
    with bpy.data.libraries.load(str(RUNTIME), link=False) as (source, loaded):
        loaded.objects = list(source.objects)
    for obj in loaded.objects:
        if obj is not None:
            bpy.context.collection.objects.link(obj)
    root = next(obj for obj in loaded.objects if obj and obj.name == R)
    if len(kit.descendants(root)) != len([obj for obj in loaded.objects if obj is not None]):
        raise RuntimeError("Runtime file contains objects outside its figure")
    if root.get("sourceFingerprint") != SOURCE_FINGERPRINT or root.get("recipeFingerprint") != RECIPE_FINGERPRINT:
        raise RuntimeError("Runtime provenance differs from the accepted copy")
    for obj in kit.descendants(root):
        if obj.type != "MESH":
            continue
        for slot in obj.material_slots:
            material = slot.material
            if material is None:
                continue
            base = re.sub(r"(?:\.\d{3})+$", "", material.name)
            if base != material.name:
                shared = bpy.data.materials.get(base)
                if shared is not None:
                    slot.material = shared
                else:
                    material.name = base
    root["arenaReviewedAO"] = True
    root["runtimeCopySource"] = "runtime/" + RUNTIME.name
    kit.refresh()
    return root
